#pragma once
#include <cstddef>
#include <cstdint>

bool passwordMatches(const char* provided, const char* configured);

// Fixed RAM only. Cookies are random IDs generated by the platform, never passwords.
class SessionAuth {
 public:
  static constexpr const char* CookieName = "purifier_session";
  static constexpr uint32_t IdleTimeoutMs = 30 * 60 * 1000;
  bool create(const char* randomToken, uint32_t now);
  bool accept(const char* cookieHeader, uint32_t now);
  void logout(const char* cookieHeader);
 private:
  struct Session { char token[33] = {}; uint32_t lastSeen = 0; } sessions_[2];
  static bool readCookie(const char* header, char token[33]);
};
